(() => {
  'use strict';
  let state;
  const el=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const error=e=>{el('bundleError').hidden=false;el('bundleError').textContent=e.message;};
  async function call(url,body){const r=await fetch(url,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-Bundle-CSRF':state.csrf}:{},body:body?JSON.stringify(body):undefined});const j=await r.json();if(!r.ok)throw new Error(typeof j.detail==='string'?j.detail:'操作失败，请刷新后重试');return j;}
  const modes={fixed:'固定搭配',random:'随机搭配',custom:'客户自选'};
  let editingCategoryId;
  function renderFlavors(flavors){el('bundleFlavors').innerHTML=flavors.map(f=>`<div class="col-md-4"><label><input type="checkbox" data-pool="${f.id}" ${f.active?'':'disabled'}> ${esc(f.name)}${f.active?'':'（不可用）'}</label><input aria-label="${esc(f.name)}数量" class="form-control d-inline-block w-auto" type="number" min="0" value="0" data-qty="${f.id}" ${f.active?'':'disabled'}></div>`).join('');}
  function reset(){el('bundleForm').reset();el('bundleId').value='';el('bundleFormTitle').textContent='新增福袋';editingCategoryId=state.category_id;renderFlavors(state.flavors);}
  async function load(){state=await call('/api/bundles/manage/'+window.bundleCategoryId);el('bundleLimit').value=state.rule.max_portions;
    el('bundleList').innerHTML=`<div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>福袋名称</th><th>模式</th><th>库存模式/份数/成本</th><th>每份支数</th><th>VIP价格</th><th>状态</th><th>操作</th></tr></thead><tbody>${state.bundles.map(b=>`<tr><td><strong>${esc(b.name)}</strong>${b.error?'<div class="text-danger">'+esc(b.error)+'</div>':''}</td><td>${esc(modes[b.config.mode]||b.config.mode)}</td><td>${b.inventory.mode==='independent'?`独立库存 · 剩余${esc(b.inventory.remaining)}份 · 进货价¥${(b.inventory.cost_cents/100).toFixed(2)}`:`扣现有口味库存 · 当前配置可组成${esc(b.available_portions)}份`}</td><td>${b.config.units}支</td><td>¥${esc(b.config.prices.regular)}</td><td>${b.enabled?'启用':'停用'}</td><td class="text-nowrap"><button class="btn btn-sm btn-outline-primary" data-edit="${b.id}">编辑</button> <button class="btn btn-sm btn-outline-secondary" data-action="${b.enabled?'disable':'enable'}" data-id="${b.id}">${b.enabled?'停用':'启用'}</button> <button class="btn btn-sm btn-outline-danger" data-action="delete" data-id="${b.id}">归档</button></td></tr>`).join('')||'<tr><td colspan="7" class="text-muted text-center">暂无福袋，点击新增福袋开始配置。</td></tr>'}</tbody></table></div>`;
    reset();
  }
  el('bundleForm').onsubmit=async e=>{e.preventDefault();try{const prices={regular:el('bundleRegular').value};if(el('bundleLevel1').value!=='')prices.level1=el('bundleLevel1').value;if(el('bundleLevel2').value!=='')prices.level2=el('bundleLevel2').value;const mode=el('bundleMode').value,components=[],pool=[];document.querySelectorAll('[data-qty]').forEach(i=>{if(Number(i.value)>0)components.push({product_id:Number(i.dataset.qty),quantity:Number(i.value)});});document.querySelectorAll('[data-pool]:checked').forEach(i=>pool.push(Number(i.dataset.pool)));await call('/api/bundles/manage/'+editingCategoryId,{id:el('bundleId').value?Number(el('bundleId').value):null,name:el('bundleName').value,aliases:el('bundleAliases').value.split('\n').map(s=>s.trim()).filter(Boolean),enabled:el('bundleEnabled').checked,inventory_mode:el('bundleStockMode').value,cost_price:el('bundleCost').value,config:{mode,units:Number(el('bundleUnits').value),max_per_flavor:Number(el('bundleMax').value),allow_repeat:el('bundleRepeat').checked,show_flavors:el('bundleShow').checked,components,pool,prices}});await load();reset();el('bundleError').hidden=true;}catch(e){error(e);}};
  el('bundleList').onclick=async e=>{const t=e.target;try{if(t.dataset.edit){const b=state.bundles.find(b=>b.id===Number(t.dataset.edit)),c=b.config;reset();editingCategoryId=b.category_id;renderFlavors(b.flavors);el('bundleId').value=b.id;el('bundleFormTitle').textContent='编辑福袋';el('bundleName').value=b.name;el('bundleAliases').value=b.aliases.join('\n');el('bundleMode').value=c.mode;el('bundleUnits').value=c.units;el('bundleMax').value=c.max_per_flavor;el('bundleRepeat').checked=c.allow_repeat;el('bundleShow').checked=c.show_flavors;el('bundleEnabled').checked=!!b.enabled;el('bundleRegular').value=c.prices.regular;el('bundleLevel1').value=c.prices.level1??'';el('bundleLevel2').value=c.prices.level2??'';document.querySelectorAll('[data-pool]').forEach(i=>i.checked=c.pool.includes(Number(i.dataset.pool)));document.querySelectorAll('[data-qty]').forEach(i=>i.value=(c.components.find(r=>r.product_id===Number(i.dataset.qty))||{}).quantity||0);el('bundleForm').scrollIntoView({behavior:'smooth'});}else if(t.dataset.action){if(t.dataset.action==='delete'&&!confirm('归档福袋配置？历史成交快照将保留。'))return;await call('/api/bundles/'+t.dataset.id+'/status',{action:t.dataset.action});await load();}}catch(e){error(e);}};
  el('resetBundle').onclick=reset;
  el('bundleList').addEventListener('click',e=>{if(e.target.dataset.edit){const b=state.bundles.find(b=>b.id===Number(e.target.dataset.edit));el('bundleStockMode').value=b.inventory.mode;el('bundleCost').value=(b.inventory.cost_cents/100).toFixed(2);el('bundleStockResult').textContent=`剩余${b.inventory.remaining}份`;el('bundleShow').checked=true;el('bundleStockAudit').innerHTML='<h6>独立库存流水（最近50条）</h6>'+b.inventory_movements.map(r=>`<div>#${esc(r.id)} ${esc(RainbowBusinessTime.format(r.created_at))} · ${esc(r.kind)} · ${esc(r.quantity)}份 · 成本¥${(r.cost_cents/100).toFixed(2)} · ${esc(r.actor)} · ${esc(r.operation_key)}</div>`).join('');}});
  const stockStorage='rainbowBundleStockOperation';
  let stockOperation=null;try{stockOperation=JSON.parse(sessionStorage.getItem(stockStorage)||'null');}catch(e){error(new Error('库存操作记录无法读取，请先核对流水再操作'));}
  el('adjustBundleStock').onclick=async()=>{try{const id=Number(el('bundleId').value);if(!id||el('bundleStockMode').value!=='independent')throw new Error('请先选择已保存的独立库存福袋');const body={action:el('bundleStockAction').value,quantity:el('bundleStockQuantity').value,cost_price:el('bundleCost').value};const signature=JSON.stringify([id,body]);if(stockOperation&&stockOperation.signature!==signature)throw new Error('前次库存提交结果未知，请先核对流水；不能换内容再次提交');if(!stockOperation){stockOperation={signature,key:crypto.randomUUID()};sessionStorage.setItem(stockStorage,JSON.stringify(stockOperation));}const result=await call('/api/bundles/'+id+'/inventory',{...body,operation_id:stockOperation.key});stockOperation=null;sessionStorage.removeItem(stockStorage);await load();el('bundleStockResult').textContent=`已记录流水${result.movement_id}，剩余${result.inventory.remaining}份`;}catch(e){error(e);}};
  el('newBundle').onclick=()=>{reset();el('bundleForm').scrollIntoView({behavior:'smooth'});el('bundleName').focus();};
  el('saveLimit').onclick=async()=>{try{await call('/api/settings/bundles',{max_portions:Number(el('bundleLimit').value)});el('bundleError').hidden=true;}catch(e){error(e);}};
  async function userPrice(remove){try{const id=Number(el('bundleId').value);if(!id)throw new Error('请先点击已有福袋的编辑按钮');if(!remove&&el('bundlePriceValue').value==='')throw new Error('请填写单独售价');await call('/api/bundles/'+id+'/user-price',{user_id:Number(el('bundlePriceUser').value),price:remove?null:el('bundlePriceValue').value});el('bundlePriceResult').textContent='已保存';}catch(e){error(e);}}
  el('saveBundleUserPrice').onclick=()=>userPrice(false);el('deleteBundleUserPrice').onclick=()=>userPrice(true);
  load().catch(error);
})();
